import json,copy
from pathlib import Path
from content_helper import case,rows
rows.clear()
case('P214','A_01943',['用高尔夫球杆作用于沙坑','观察握杆、挥动或下压与躯干和脚部支撑的配合。','杆头与沙接触的位置和时刻应与手臂动作相符。','沙可被压入、带起或散落，不要求片段中一定有可见球飞出。','若沙飞散或杆头离开，观察重力、堆积及随挥，不要求沙坑大幅改变。','只有瞄准准备，实际杆头与沙作用不足以评价时选择无法判断。','人体控杆、杆头沙面作用与沙粒运动'],['Work a golf club into bunker sand','Consider grip, swing or downward pressure, torso coordination, and foot support.','Clubhead–sand contact location and timing should match arm action.','Sand may compress, lift, or scatter. A visible departing ball is not required.','If sand scatters or the head withdraws, consider gravity, accumulation, and follow-through without requiring a major bunker change.','Choose unable to judge if only aiming is shown and actual club–sand action cannot be assessed.','Club control, clubhead–sand action, and grain motion'])
case('P215','A_03756',['用乒乓球拍击球','观察握拍、手腕前臂和身体重心配合，不指定技术姿势。','拍面与球的相遇时刻应与球的速度或方向变化相联系。','球可快速离拍，不要求出现沙土飞溅，也不要求看清细微旋转。','若球落台、反弹或离开画面，评价可见轨迹，不推断画面外结果。','只有准备挥拍，实际击球关系不足以评价时选择无法判断。','人体挥拍、乒乓球拍接触与球的轨迹'],['Strike a table-tennis ball with a paddle','Consider grip, wrist–forearm action, and weight coordination without prescribing technique.','Paddle–ball encounter timing should relate to changes in ball speed or direction.','The ball may leave rapidly. Sand spray and visibly resolved fine spin are not required.','If it lands, bounces, or leaves view, assess the visible trajectory without inferring off-screen results.','Choose unable to judge if only preparation is shown and actual striking cannot be assessed.','Paddle control, table-tennis contact, and ball trajectory'])
case('P216','A_03646',['挥动高尔夫球杆击打球座上的球','观察握杆、肩髋转动、重心转移和随挥，不限定唯一姿势。','杆头经过球位的时刻应与球离座相关，手与杆的连接应连续。','球可被击出，不要求练习垫或草地必定飞散。','若球可见，观察离座与飞行，球离开画面后不推断落点。','只有瞄准或上杆准备，实际击球不足以评价时选择无法判断。','人体挥杆、杆头球座接触与球离座运动'],['Swing a golf club at a teed ball','Consider grip, shoulder–hip rotation, weight transfer, and follow-through without prescribing one technique.','Head passage through the ball location should relate to ball departure, with continuous hand–club connection.','The ball may launch. Mat or turf spray is not required.','If visible, consider departure and flight without inferring a landing outside the frame.','Choose unable to judge if only aiming or backswing preparation is shown and actual striking cannot be assessed.','Body swing, clubhead–tee-ball contact, and ball departure'])
c=copy.deepcopy(rows[-1]);c.update(sample_id='P217',media_id='A_03512',shared_task_basis='与P216同为球座上高尔夫球的挥杆击打，垫面和草地均不强制飞散');rows.append(c)
case('P218','A_03511',['从草面球位挥动高尔夫球杆','观察双手握杆、上身旋转与下肢平衡。','杆头轨迹应与握持和球位对应，可见球的变化应与接触时刻相关。','球可被带离球位，草面可以基本保持，不强制要求草屑或沙粒。','若随挥或球继续飞行，观察动作连续性，不推断不可见落点。','只有瞄准或上杆，实际挥击不足以评价时选择无法判断。','人体转动、球杆连续轨迹与球位作用'],['Swing a golf club from a grass-level ball position','Consider two-hand grip, torso rotation, and lower-body balance.','Head trajectory should correspond to grip and ball location, with visible ball changes related to contact timing.','The ball may leave its position while grass remains largely unchanged. Turf or sand spray is not required.','If follow-through or flight is visible, consider continuity without inferring an unseen landing.','Choose unable to judge if only aiming or backswing is shown and actual striking cannot be assessed.','Body rotation, continuous club trajectory, and action at the ball position'])
case('P219','A_02329',['完成高尔夫挥杆的随挥','观察双手持杆、肩髋旋转和挥杆后站姿平衡。','球杆应随双手连续运动，不要求重新出现已经过去的碰撞。','杆体可以快速转动，若球在画面内，其运动应有合理连续性。','观察随挥减速和身体恢复支撑，不推断未显示的击球成功或落点。','随挥过短或遮挡导致实际人杆运动无法评价时选择无法判断。','人体随挥、球杆惯性运动与站姿支撑'],['Follow through after a golf swing','Consider two-hand grip, shoulder–hip rotation, and post-swing balance.','The club should move continuously with the hands. An earlier collision need not reappear.','The club may rotate rapidly. Any visible ball motion should remain continuous.','Consider deceleration and restored body support without inferring unseen shot success or landing.','Choose unable to judge if follow-through is too brief or obscured to assess actual person–club motion.','Body follow-through, club inertia, and stance support'])
case('P220','A_01981',['持握并调整网球拍','观察手指握柄、手腕调向和身体准备姿势。','球拍应由手部合理承托，握柄与拍框的结构应连续。','球拍可转向或小幅摆动，本任务不强制要求球出现、击球或拍线变形。','若调整后停住，观察手部控制及拍体停止，不推断下一次击球。','手柄被遮挡且实际持握关系无法评价时选择无法判断。','手部握拍、拍体调向与人体平衡'],['Hold and adjust a tennis racket','Consider handle grip, wrist orientation, and body readiness.','The hand should plausibly support the racket, with continuous handle–frame structure.','The racket may turn or move slightly. A ball, strike, or string deformation is not required for this holding task.','On stopping, consider hand control and racket deceleration without inferring the next shot.','Choose unable to judge if the grip is obscured and actual holding cannot be assessed.','Hand grip, racket orientation, and body balance'])
case('P221','A_01937',['用球棒击打汽车挡风玻璃','观察双手控棒、挥动和身体支撑。','棒与玻璃的接触应与挥动对应，玻璃变化应从合理作用位置发展。','挡风玻璃可产生裂纹、局部变形或碎裂，不要求整面像无夹层薄玻璃一样散落。','若碎片脱离或球棒回撤，观察重力、保留支撑及停止。','只有持棒瞄准，实际作用不足以评价时选择无法判断。','人体挥棒、挡风玻璃接触与局部破裂响应'],['Strike a car windshield with a bat','Consider bat control, swinging, and body support.','Bat–glass contact should match the swing, with changes developing from plausible action locations.','A windshield may crack, deform locally, or break. Complete loose-fragment collapse is not required.','If fragments detach or the bat withdraws, consider gravity, retained support, and stopping.','Choose unable to judge if only aiming is shown and actual action cannot be assessed.','Body swing, windshield contact, and local fracture response'])
case('P222','A_02044',['用锤作用于木框玻璃窗','观察握锤、手臂推压或敲击与身体平衡。','锤头与玻璃作用位置应与手部动作相符，窗框应合理承托。','新裂纹、压损或碎片应与作用相关，已有白色圆痕不代表当前操作成功。','若碎片落下或锤离开，观察重力和残留玻璃支撑，不要求整窗崩落。','实际锤头接触被遮挡或只有准备时选择无法判断。','人体控锤、窗玻璃作用与框内支撑'],['Apply a hammer to a framed glass window','Consider grip, arm pressure or tapping, and balance.','Head contact should correspond to hand action, with plausible frame support.','New cracks, damage, or fragments should relate to action. Existing white marks do not establish current success.','If pieces fall or the hammer withdraws, consider gravity and remaining glass support without requiring total collapse.','Choose unable to judge if actual contact is obscured or only preparation is shown.','Hammer control, window-glass action, and frame support'])
case('P223','A_04724',['扶持竹筒并用细木棍操作','观察一手承托竹筒、另一手控棍与躯干协调。','棍与竹筒开口或内部的可见接触应与手部运动对应。','竹筒应保持合理形状和承托，不凭烟熏痕迹推断当下点火或内部物质。','若棍退出或竹筒移近已有火焰，观察支撑与可见火源关系，不要求燃烧突然增强。','竹筒内部不可见不扣分，实际控筒控棍也不足以评价时选择无法判断。','双手控筒控棍、竹筒承托与可见接触'],['Support a bamboo tube while using a thin stick','Consider one-hand tube support, other-hand stick control, and torso coordination.','Visible stick contact at the opening or interior should correspond to hand motion.','The tube should retain plausible form and support. Soot does not establish current ignition or unseen contents.','On withdrawal or approach to existing flames, consider support and visible fire location without requiring sudden flame growth.','Do not penalize an unseen interior. Choose unable to judge if actual tube and stick control also cannot be assessed.','Two-hand tube–stick control, bamboo support, and visible contact'])
case('P224','A_04706',['把粗木段放入已有火焰的火坑','观察双手承重、弯腰降低和站姿平衡。','木段应随手移动，并在落到石块或木堆时获得合理支撑。','已有火焰可受木段位置影响，不要求粗木段立即全部燃烧。','若松手，观察木段停放或滚动及火焰烟气变化，不要求火焰必定增大。','只有举木准备，实际放置不足以评价时选择无法判断。','人体承重、木段放置与火坑支撑及火焰响应'],['Place a thick log into an already burning fire pit','Consider two-hand load support, lowering, and balance.','The log should move with the hands and acquire support from stones or wood on placement.','Existing flames may respond to log position. Immediate complete ignition is not required.','On release, consider resting or rolling and visible fire or smoke changes without requiring flame growth.','Choose unable to judge if only carrying preparation is shown and actual placement cannot be assessed.','Body load support, log placement, pit support, and flame response'])
case('P225','A_04695',['在小火旁承托竹筒','观察蹲姿、双手承托长竹筒和局部调整。','竹筒的重量支撑与手部位置应相容，竹筒和火源的相对位置应连续。','已有火焰可摆动，不要求竹筒自行点燃、软化或立刻改变颜色。','若竹筒转动或移开，观察重力与支撑转换，烟气按可见程度评价。','若承托接触与火源关系均不可见，无法评价实际交互时选择无法判断。','人体低位承托、竹筒连续性与火源位置关系'],['Support a bamboo tube beside a small fire','Consider crouching, two-hand support of the long tube, and local adjustments.','Weight support should fit hand positions, with continuous tube–fire spatial relations.','Existing flames may flicker. Tube ignition, softening, or immediate color change is not required.','If turned or withdrawn, consider gravity and support transfer, assessing smoke only where visible.','Choose unable to judge if support contact and fire relations are both hidden and actual interaction cannot be assessed.','Low-level body support, tube continuity, and fire-source spatial relations'])
case('P227','A_04669',['向燃烧的枝条堆添加木柴','观察双手持柴、前伸放置与脚部平衡。','木柴应通过手的动作接近并接触枝条堆，不应忽略堆体的承托。','枝条可局部移位，已有火焰烟气可摆动，不要求新柴立即完全着火。','若松手，观察柴条停止、滑动或落入堆内及可见火焰变化。','只有拿柴准备，实际放置不足以评价时选择无法判断。','人体放柴、枝条堆承托与已有火焰连续性'],['Add firewood to a burning branch pile','Consider two-hand holding, reaching placement, and foot balance.','Wood should approach and contact the pile through hand action, respecting pile support.','Branches may shift locally and existing flames or smoke may fluctuate. Immediate complete ignition is not required.','On release, consider resting, sliding, or falling into the pile and visible flame changes.','Choose unable to judge if only preparation is shown and actual placement cannot be assessed.','Body placement, branch-pile support, and existing-flame continuity'])
case('P228','A_04544',['抛接燃烧的长柄火把','观察双手交替释放、接取及身体平衡。','手接触应对应火把的释放与停止，自由段运动应与之前抛动相关。','火把可旋转，火焰应与燃烧端保持合理来源关系，不要求火焰固定形状。','若接住或停止，观察手部缓冲和火焰随运动摆动，不要求每次完整循环都在画面内。','只有举火把展示，实际抛接不足以评价时选择无法判断。','人体抛接、火把飞行与燃烧端火焰'],['Juggle burning long-handled torches','Consider alternating releases and catches and body balance.','Hand contact should correspond to release and arrest, with free motion related to the preceding throw.','Torches may rotate. Flames should retain a plausible burning-tip source without a fixed shape.','On catching or stopping, consider hand cushioning and moving flames without requiring every complete cycle in view.','Choose unable to judge if only display is shown and actual juggling cannot be assessed.','Body juggling, torch flight, and burning-tip flames'])
case('P229','A_04539',['提持燃烧的煤油灯','观察提柄握持、手臂承托和轻微调整。','提柄、灯体与手的连接应连续，灯体运动应与承托相关。','灯内火焰可闪动，反光罩可随灯移动，不要求当场点火或外壳燃烧。','若灯摆动或停住，观察重力方向、手部控制及灯内火焰来源。','灯体与手的承托均无法辨认时选择无法判断。','人体提持、煤油灯结构承托与灯内火焰'],['Hold a burning kerosene lamp by its handle','Consider handle grip, arm support, and small adjustments.','Handle, lamp body, and hand connections should remain continuous, with motion related to support.','The internal flame may flicker and the reflector may move with the lamp. New ignition or casing combustion is not required.','On swinging or stopping, consider gravity, hand control, and the internal flame source.','Choose unable to judge if actual hand–lamp support cannot be distinguished.','Body holding, lamp structure and support, and internal flame'])
case('P230','A_04494',['把长木段安放到火堆旁或火堆上','观察弯腰、双手移动长木段与站姿平衡。','木段应在手、地面或火堆间得到连续支撑，放置接触应与手部动作对应。','已有火焰可绕木段变化，不要求长木段立即烧透或形成固定火焰大小。','若松手，观察木段的停止、滚动和火堆承托。','只有弯腰准备，实际放置不足以评价时选择无法判断。','人体搬放、长木段地面接触与火堆支撑'],['Position a long log beside or on a fire','Consider leaning, two-hand log movement, and balance.','Support should transfer continuously among hands, ground, and pile, with placement contact related to hand action.','Existing flames may change around the log. Immediate thorough burning or a fixed flame size is not required.','On release, consider resting, rolling, and pile support.','Choose unable to judge if only bending preparation is shown and actual placement cannot be assessed.','Body placement, long-log ground contact, and fire-pile support'])
case('P231','A_04439',['操控燃烧的长柄火把','观察双手换握、抬动与躯干平衡。','火把应在握持时由手支撑，若释放则按自由运动评价，不能要求始终与手连接。','燃烧端可移动并带动火焰摆动，不要求火把刚体本身弯曲。','若转动、接取或停止，观察惯性、重力及火焰与燃烧端的连续关系。','只有准备且控把或实际运动不足以评价时选择无法判断。','双手火把控制、杆体运动与燃烧端火焰'],['Manipulate burning long-handled torches','Consider regripping, lifting, and torso balance.','Hands should support held torches. Assess any released torch as free motion without requiring continued hand attachment.','Burning ends may move and carry fluctuating flames. Shaft bending is not required.','On rotating, catching, or stopping, consider inertia, gravity, and flame-source continuity.','Choose unable to judge if only preparation is shown and control or actual motion cannot be assessed.','Two-hand torch control, shaft motion, and burning-tip flames'])
case('P232','A_04424',['把金属丝保持在喷灯火焰中','观察手指夹持金属丝与手腕精细定位。','丝与喷嘴的空间关系应连续，火焰应从喷嘴合理喷出。','金属丝受热可以暂时没有明显变化，不要求短片内熔断、发红或弯曲。','若丝移动或火焰摆动，观察夹持与热源位置，不推断不可见温度。','丝、手或火焰作用位置无法分辨，实际加热关系不足以评价时选择无法判断。','手部定位、金属丝承托与喷灯火焰来源'],['Hold a metal wire in a blowtorch flame','Consider finger grip and fine wrist positioning.','Wire–nozzle spatial relations should remain continuous, with flame emerging plausibly from the nozzle.','Heating may produce no immediate visible wire change. Melting, glowing, or bending within the clip is not required.','On wire motion or flame fluctuation, consider grip and heat-source position without inferring unseen temperature.','Choose unable to judge if wire, hand, or flame position cannot be distinguished enough to assess heating.','Hand positioning, wire support, and blowtorch flame source'])
case('P233','A_04417',['戴手套托持一端燃烧的木段','观察双手承托与手臂控制，不按是否看向镜头判断物理合理性。','木段应由手合理承托，燃烧端与火焰来源应连续。','火焰可自然摆动，不要求整段木头立刻燃烧或明显缩短。','若木段调整位置，观察惯性、重力及火焰方向变化。','实际手木承托或火源位置无法评价时选择无法判断。','人体托木、木段支撑与端部燃烧'],['Support a log burning at one end with gloved hands','Consider two-hand support and arm control. Looking at the camera is not itself a physical error.','Hands should plausibly support the log, with continuous burning-end flame sourcing.','Flames may fluctuate naturally. Immediate whole-log burning or visible shortening is not required.','If repositioned, consider inertia, gravity, and flame direction changes.','Choose unable to judge if actual hand–log support or flame location cannot be assessed.','Body holding, log support, and end combustion'])
case('P234','A_04407',['操控带火焰的球形道具','观察双手对手柄或支杆的控制和身体协调。','球、可见连接件与手的关系应连续，按实际连接约束评价，不强制视为自由抛球。','球形燃烧端可移动，火焰应具有合理来源，不要求球体本身明显变形。','若球转动或停止，观察约束运动和火焰摆动，不推断隐藏机构。','连接关系无法辨认且实际运动不足以评价时选择无法判断。','人体控柄、球形道具约束运动与火焰来源'],['Manipulate flaming spherical props','Consider hand control of handles or rods and body coordination.','Balls, visible connectors, and hands should remain coherent. Use visible constraints rather than assuming freely thrown balls.','Spherical burning ends may move with plausibly sourced flames. Obvious ball deformation is not required.','On rotation or stopping, consider constrained motion and flame fluctuation without inferring hidden mechanisms.','Choose unable to judge if connection relations are unclear and actual motion cannot be assessed.','Handle control, constrained spherical-prop motion, and flame sources'])
case('P235','A_04337',['按动厨房喷灯的点火机构','观察扶持筒体、手指按动与喷嘴定向的协调。','按键动作与喷嘴火焰的开始、保持或停止应有合理关系。','火焰可从喷嘴出现，不要求金属筒体变形或燃烧。','若松开或移动，观察火焰随控制和喷嘴位置变化，不限定固定长度。','只有拿灯展示或点火部位完全不可见时选择无法判断。','手指点火、喷灯握持与喷嘴火焰响应'],['Activate a kitchen torch ignition mechanism','Consider cylinder support, finger activation, and nozzle orientation.','Button action should plausibly relate to flame onset, maintenance, or stopping.','A flame may emerge from the nozzle. Cylinder deformation or combustion is not required.','On release or movement, consider control and nozzle-related flame changes without prescribing fixed length.','Choose unable to judge if only display is shown or the ignition area is entirely hidden.','Finger activation, torch grip, and nozzle-flame response'])
case('P236','A_04317',['用长金属杆操作炉口','观察双手控杆、前伸及身体承力支撑。','杆端与炉口的进入或接触应与手部动作相关，炉体应有合理支撑。','已有火焰和火星可变化，不要求杆立刻熔化或炉内材料完整可见。','若杆退出或火星飞出，观察杆体连续性、火星轨迹及火焰来源。','炉口遮挡导致实际杆端作用不足以评价时选择无法判断。','人体控杆、炉口接触与火焰火星运动'],['Operate at a furnace opening with a long metal rod','Consider two-hand rod control, reaching, and load-bearing stance.','Rod entry or contact should correspond to hand action, with plausible furnace support.','Existing flames and sparks may vary. Immediate rod melting or a complete view of furnace contents is not required.','On withdrawal or spark emission, consider rod continuity, spark trajectories, and flame sources.','Choose unable to judge if occlusion prevents assessment of actual rod-end action.','Rod control, furnace-opening contact, and flame and spark motion'])
case('P237','A_04290',['用木棍拨动燃烧的木柴','观察弯腰、双手推拨和脚部支撑。','棍端与木柴的作用应和手部推压对应，不要求手直接接触燃烧木柴。','木柴可局部移动，火焰烟气可随位置变化，不要求火立刻熄灭或增强。','若拨动后停住，观察木柴承托、棍端退出和可见火星。','只有持棍准备，实际拨动不足以评价时选择无法判断。','人体推拨、棍柴接触与火堆支撑'],['Adjust burning logs with a wooden stick','Consider leaning, two-hand pushing, and foot support.','Stick-end action on wood should correspond to hand pressure. Direct hand contact with burning logs is not required.','Logs may shift locally, affecting flames or smoke. Immediate extinction or growth is not required.','On stopping, consider log support, stick withdrawal, and any visible sparks.','Choose unable to judge if only stick preparation is shown and actual adjustment cannot be assessed.','Body pushing, stick–log contact, and fire-pile support'])
case('P238','A_04274',['朝小蜡烛附近按动喷瓶','观察蹲姿、握瓶、食指按压及喷嘴定向。','喷液若可见，其出现应与按压和喷嘴位置相联系，蜡烛应保持地面支撑。','液滴可形成喷雾，已有火焰可响应，不推断粉色液体成分，也不强制要求燃烧或熄灭。','若液滴落地或火焰改变，观察运动连续性及火源关系。','只有对准准备或喷液与火源关系不足以评价时选择无法判断。','手部按喷、液滴运动与蜡烛火焰响应'],['Operate a spray bottle near a small candle','Consider crouching, bottle grip, trigger pressure, and nozzle orientation.','Any visible liquid should relate to activation and nozzle position, with the candle supported on the ground.','Droplets may form mist and the existing flame may respond. Do not infer pink-liquid composition or require ignition or extinction.','If drops land or the flame changes, consider continuous motion and fire-source relations.','Choose unable to judge if only aiming is shown or spray–fire relations cannot be assessed.','Trigger operation, droplet motion, and candle-flame response'])
Path(__file__).with_name('batch_29.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
